package org.anime_game_servers.game_data_models.loader.enums

import kotlinx.serialization.KSerializer
import kotlin.enums.EnumEntries
import kotlin.reflect.KClass
import org.anime_game_servers.core.base.interfaces.IntKey

/**
 * Base interface for the metadata objects generated by ksp.
 */
interface EnumMetadata<T : Enum<T>> {
    val unknownEntry: T
    val noneEntry: T?
    val kClass: KClass<T>
    val serializer: KSerializer<T>
    val values: EnumEntries<T>

    fun fromIntKey(intKey: Int): T?
    fun fromStringKey(stringKey: String): T?

    fun fromIntKeyOrUnknown(intKey: Int): T = fromIntKey(intKey) ?: unknownEntry
    fun fromStringKeyOrUnknown(stringKey: String): T = fromStringKey(stringKey) ?: unknownEntry
}
